import os
import re
import datetime
from taf.ul.sc.util import util
from moler.util.moler_test import MolerTest
from moler.exceptions import CommandFailure


class GenericEnb(object):
    def __init__(self, enb, base_state='LINUX'):
        self.enb = enb
        self.base_state = base_state
        self._sw_version = None
        self._oam_ip = None
        self._cell_count = None
        self._hardware_product_code = None
        self._swconfig_path = "/rom/swconfig.txt"

    @MolerTest.raise_background_exceptions(check_steps_end=True)
    def connect_to_enb(self):
        """
        The keyword creates the gNB device object in the FCT state based on the given device name.
        :return: None
        :rtype: None
        """
        self.enb.connect()
        self.enb.device.goto_state(self.base_state)

        MolerTest.steps_end()

    @property
    def sw_version(self):
        if self._sw_version is None:
            self.get_version()
        return self._sw_version

    def get_version(self):
        """
        Get Software version from TargetDB.
        :return: Software version
        :rtype: unicode
        """

        self._sw_version = self.enb.extract_grep_value(options="'softwareReleaseVersion' /rom/TargetBD*.xml",
                                                       pattern=r'softwareReleaseVersion="(.*?)"')
        return self._sw_version

    @property
    def oam_ip(self):
        if self._oam_ip is None:
            self.get_oam_ip()
        return self._oam_ip

    def get_oam_ip(self):
        """
        Get OAM IP address from trs.
        :return: OAM IP address
        :rtype: unicode
        """
        self._oam_ip = self.enb.extract_grep_value(options="'oamIpAddr' /ffs/run/btsom/config/active/trs.xml",
                                                   pattern=r">([\d+.]+)<")
        return self._oam_ip

    @property
    def hardware_product_code(self):
        if self._hardware_product_code is None:
            self.get_hardware_product_code()
        return self._hardware_product_code

    def get_hardware_product_code(self):
        """
        Get hardware product code.
        :return: Hardware product code
        :rtype: str
        """

        file_content = self.enb.get_file_content(path_to_file="/proc/device-tree/board-identity/unit-id")
        _hardware_product_code_regex = r"(?P<HARDWARE_PRODUCT_CODE>^(F.*?)\00)"
        search_obj = re.search(_hardware_product_code_regex, file_content[0])

        if search_obj:
            self._hardware_product_code = search_obj.group("HARDWARE_PRODUCT_CODE")

        return self._hardware_product_code

    @property
    def cell_count(self):
        if self._cell_count is None:
            self.get_enb_cell_count()
        return self._cell_count

    def get_enb_cell_count(self):
        """
        Count eNB cells.
        :return: Number of eNB cells
        :rtype: int
        """
        self.enb.device.goto_state(self.base_state)
        cmd_grep = self.enb.device.get_cmd(cmd_name="grep",
                                           cmd_params={
                                               "options": "-E  LCELL-[0-9] /ffs/run/btsom/config/active/bts.xml"
                                           }
                                           )
        file_content = cmd_grep()

        unique_cells = set()
        for element in file_content["LINES"]:
            unique_cells.add(re.search(r"LCELL-[0-9]", element).group(0))

        self._cell_count = len(unique_cells)

        return self._cell_count

    def enable_ssh(self):
        """
        Enable SSH.
        :return: `True` if command was successful, `False` otherwise
        :rtype: bool
        """
        cmd_enable_ssh = self.enb.device.get_cmd(cmd_name="enable_ssh")
        cmd_result = cmd_enable_ssh()
        return cmd_result["SUCCESS"]

    def enable_rnd_ports(self):
        """
        Enable R&D Ports Service on FZP.
        :return: `True` if command was successful, `False` otherwise
        :rtype: bool
        """
        cmd_enable_rnd_ports = self.enb.device.get_cmd(cmd_name="enable_rnd_ports")
        cmd_result = cmd_enable_rnd_ports(timeout=15)
        return cmd_result["SUCCESS"]

    def _s02iptables(self, action, extend_timeout=None):
        """
        S02iptables main method.
        Waits for enable_firewall() or disable_firewall() helper methods.
        :param action: start or stop param obtained from helper method.
        :param extend_timeout: Ignore time limit for process execution.
        :return: None
        """
        cmd_s02iptables = self.enb.device.get_cmd(cmd_name="s02iptables",
                                                  cmd_params={"options": action})
        cmd_s02iptables(timeout=extend_timeout)

    def enable_firewall(self):
        """
        _s02iptables helper method.
        Performs S02iptables start.
        :return: None
        """
        self._s02iptables(action="start")

    def disable_firewall(self):
        """
        _s02iptables helper method.
        Performs S02iptables stop.
        :return: None
        """
        self._s02iptables(action="stop")

    def get_aashel_snapshot(self, local_dir, timeout=900):
        """
        Create snapshot.
        :return: snapshot file path.
        :rtype: str
        """
        self.enb.device.goto_state(state="AASHELL")
        now = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
        file_name = "eNB_Snapshot{}.zip".format(now)
        cmd_log = self.enb.device.get_cmd(cmd_name="log",
                                          cmd_params={"options": "-a -z",
                                                      "filename": file_name})

        cmd_log(timeout=timeout)
        self.enb.device.goto_state(state=self.base_state)

        util().download_files(local_dir=local_dir,
                              remote_file=file_name,
                              remote_device_name=self.enb.device.name,
                              remote_dir="/tmp",
                              hops=[self.enb.ws_name])

        return os.path.join("/tmp", file_name)

    def remove_swconfig(self):
        """
        Remove swconfig file.
        :return: None
        :rtype: None
        """
        self.enb.remove_file(self._swconfig_path)

    def get_enb_config(self, local_dir):
        """
        Download eNB config.
        :return: None
        :rtype: None
        """
        util().download_files(local_dir=local_dir,
                              remote_file="SCFC_*.xml",
                              remote_device_name=self.enb.device.name,
                              remote_dir="/ffs/run/btsom/config/active/",
                              hops=[self.enb.ws_name])

    def get_swconfig(self, local_dir):
        """
        Download swconfig.txt file.
        :return: None
        :rtype: None
        """
        util().download_files(local_dir=local_dir,
                              remote_file=os.path.basename(self._swconfig_path),
                              remote_device_name=self.enb.device.name,
                              remote_dir=os.path.dirname(self._swconfig_path),
                              hops=[self.enb.ws_name])

    def get_raw_alarm_history(self, local_dir):
        """
        Copy RawAlarmHistory file from FZM to WS.
        :return: None
        :rtype: None
        """
        util().download_files(local_dir=local_dir,
                              remote_file="RawAlarmHistory.txt",
                              remote_device_name=self.enb.device.name,
                              remote_dir="/tmp",
                              hops=[self.enb.ws_name])

    def get_journal_files(self, local_dir):
        """
        Goes to base state, removes old journal logs and creates new.
        Downloads new logs to given destination.
        :return: None
        :rtype: None
        """
        self.enb.device.goto_state(state=self.base_state)

        try:
            self.enb.remove_file("/rom/journal*.log")
        except CommandFailure:
            pass

        cmd_journal = ("journalctl > /rom/journal.log;"
                       "journalctl -b > /rom/journal_2.log;"
                       "journalctl -ab > /rom/journal_3.log")

        cmd_cat = self.enb.device.get_cmd(cmd_name="run_script",
                                          cmd_params={"script_command": cmd_journal})
        cmd_cat(timeout=120)

        util().download_files(local_dir=local_dir,
                              remote_file="journal*.log",
                              remote_device_name=self.enb.device.name,
                              remote_dir="/rom",
                              hops=[self.enb.ws_name])

    def check_if_swconfig_exists(self):
        """
        Check if swconfig.txt exists on local enb.
        :return: True or False
        """
        return self.enb.check_if_file_exists(file_path=self._swconfig_path)

    def get_swcocnfig_md5sum(self):
        """
        Calculate md5sum of /rom/swconfig.txt file and return it.
        :return: md5sum of swconfig.txt
        """
        return self.enb.get_md5sum(path_to_file=self._swconfig_path)

    def reboot(self):
        """
        Reboot enb.
        :return: None
        """
        return self.enb.reboot(timeout=20)

    def set_swconfig(self, sw_config_path):
        """
        Copy a local swconfig file to given remote dir.
        :return: None
        :rtype: None
        """
        self.enb.device.goto_state(state=self.base_state)

        util().upload_files(local_dir=os.path.dirname(sw_config_path),
                            local_file=os.path.basename(sw_config_path),
                            remote_device_name=self.enb.device.name,
                            remote_dir=os.path.dirname(self._swconfig_path),
                            new_file_name=os.path.basename(self._swconfig_path),
                            hops=[self.enb.ws_name])

    def change_swconfig_via_aashell(self, params):
        """
        Change swconfig via AaShell.
        :param params: Dictionary with parameter and value items.
        :return: None
        :rtype: None
        """
        self.enb.device.goto_state(state="AASHELL")

        for parameter, value in params.items():
            options = "-mw {} {}".format(parameter, value)
            cmd_rad = self.enb.device.get_cmd(cmd_name="rad",
                                              cmd_params={"options": options})
            cmd_rad()

    def set_default_swconfig_via_aashell(self):
        """
        Restore factory default values.
        :return: None
        :rtype: None
        """
        self.enb.device.goto_state(state="AASHELL")

        cmd_rad = self.enb.device.get_cmd(cmd_name="rad",
                                          cmd_params={"options": "-f"})
        cmd_rad()

    def waiting_for_site_response(self, rerun=60):
        """
        Wait for ssh
        :param rerun: int, number of reruns
        :return: None
        """

        self.enb.device.goto_state(state="PROXY_PC")
        self.enb.device.goto_state(state=self.base_state, rerun=rerun)

    def get_modules(self):
        """
        Get eNB modules with theirs serial numbers.
        :return: String with modules and serial numbers
        """
        if "FCTB" in self.hardware_product_code:
            self.enb.device.goto_state(self.base_state)
            cmd_cat_option = '; for sl in /proc/device-tree/id_0*/module-identity/ ;do cat $sl/unit-id;echo -n ": "; ' \
                             'cat $sl/serial-number;echo;done '
            cmd_cat = self.enb.device.get_cmd(cmd_name="cat",
                                              cmd_params={"path": "/dev/null",
                                                          "options": cmd_cat_option
                                                          }
                                              )
            cmd_result = cmd_cat(timeout=15)
            bts_modules = None
            if cmd_result:
                modules = []
                for line in cmd_result['LINES']:
                    modules.append(line.replace('\x00', ''))
                bts_modules = ', '.join(modules)
            else:
                bts_modules = "No BTS module has been found."
            return bts_modules
        else:
            # FSMr4 eNB type not handled yet
            return None
